(959, 2987, 'ka-ge', 10, 'ვუზრუნველყოთ დადასტურებული, ხელშესახები და თვალსაჩინო მკურნალობის მეთოდების სარგებელი, როგორც ლიმფური დრენაჟის, ასევე ჩვენს მიერ შემუშავებული კანის მოვლის საშუალებების მეშვეობით.', NULL, 1, 'local', 0, '2026-01-16 14:08:58'),
(960, 2988, 'ka-ge', 10, 'რაც შეეხება ჩვენს ძირითად საქმიანობას, ჩვენ ვმუშაობთ როგორც ჩვენს თანამოაზრეებთან, ასევე ოჯახურ ბიზნესებთან ერთად სრულყოფილების მისაღწევად.', NULL, 1, 'local', 0, '2026-01-16 14:08:58'),
(961, 2989, 'ka-ge', 10, 'ფორმულირება, წარმოება და შეფუთვა ხდება საფრანგეთში. ჩვენი ნედლეული არის საფრანგეთიდან(ძირითად) ან ევროკავშირიდან. ', NULL, 1, 'local', 0, '2026-01-16 14:08:58'),
(962, 2990, 'ka-ge', 10, 'ჩვენი აქცენტი მიმართულია პროდუქტის შემადგენელი ინგრედიენტების მაღალ ხარისხზე, რომელიც იქმნება სრულფასოვნად გადამუშავებული მასალისგან. ჩვენთვის პრიორიტეტულია არა შეფუთვა, რაც გაზრდის პროდუქტის ფასს, არამედ შემადგენელი ინგრედიენტების მაღალი ხარისხი.', NULL, 1, 'local', 0, '2026-01-16 14:08:58'),
(963, 2991, 'ka-ge', 10, 'ჩვენ მუდმუვად ვითვალისწინებთ ჩვენი მომხმარებლების და პარტნიორების კრიტიკას, რაც გვეხმარება წინსვლაში', NULL, 1, 'local', 0, '2026-01-16 14:08:58'),
(964, 2992, 'ka-ge', 10, '</p>', NULL, 1, 'local', 0, '2026-01-16 14:08:58');
