(2666, '_transient_wpml_requirements', 'a:10:{i:0;a:4:{s:2:\"id\";i:1;s:7:\"isValid\";b:1;s:5:\"title\";s:12:\"Memory limit\";s:8:\"messages\";a:3:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:125:\"Your PHP memory limit is currently <strong>300M</strong>.  WPML requires at least <strong>128M</strong> to function properly.\";}i:1;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:94:\"To increase the memory limit, add this to the top of your <strong>wp-config.php</strong> file:\";}i:2;a:2:{s:4:\"type\";s:4:\"code\";s:7:\"message\";s:97:\"/** Memory Limit */\ndefine( \'WP_MEMORY_LIMIT\', \'128M\' );\ndefine( \'WP_MAX_MEMORY_LIMIT\', \'256M\' );\";}}}i:1;a:4:{s:2:\"id\";i:2;s:7:\"isValid\";b:1;s:5:\"title\";s:11:\"PHP Version\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:78:\"Your PHP version is outdated. WPML requires at least <strong>PHP 7.0</strong>.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:70:\"Contact your hosting provider to upgrade PHP to version 7.0 or higher.\";}}}i:2;a:4:{s:2:\"id\";i:3;s:7:\"isValid\";b:1;s:5:\"title\";s:16:\"Database Version\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:150:\"Your <strong>MySQL</strong> version must be at least <strong>5.6</strong>. Alternatively, you can use <strong>MariaDb</strong> version 10.1 or higher.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:61:\"Contact your hosting provider to upgrade MySQL 5.6 or higher.\";}}}i:3;a:4:{s:2:\"id\";i:4;s:7:\"isValid\";b:1;s:5:\"title\";s:18:\"WordPress REST API\";s:8:\"messages\";a:5:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:66:\"The WordPress REST API must be enabled for WPML to work correctly.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:149:\"The REST API test endpoint <strong>http://gisele.acutetest.com/wp-json/wpml/v1/rest/status?test_get_parameter=1</strong> is not responding correctly.\";}i:2;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:31:\"<strong>Common causes:</strong>\";}i:3;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:289:\"• A security or firewall plugin is blocking REST API requests<br>• The REST API has been disabled via the <code>rest_enabled</code> filter<br>• Server configuration (Apache/Nginx) is interfering with query parameters<br>• Custom rewrite rules are conflicting with WordPress routing\";}i:4;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:309:\"<strong>Troubleshooting:</strong> Try accessing <a href=\"http://gisele.acutetest.com/wp-json/wpml/v1/rest/status?test_get_parameter=1\" target=\"_blank\">the test endpoint</a> directly in your browser. It should return a JSON response with <code>\"status\":\"valid\"</code> and <code>\"get_parameters\":\"valid\"</code>.\";}}}i:4;a:4:{s:2:\"id\";i:5;s:7:\"isValid\";b:1;s:5:\"title\";s:19:\"SimpleXML Extension\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:314:\"The <a  href=\"https://www.php.net/manual/en/book.simplexml.php\" target=\"_blank\">SimpleXML extension</a> is required to use <a href=\"https://wpml.org/documentation/translating-your-contents/using-desktop-cat-tools\" target=\"_blank\">XLIFF files</a> in WPML. The libxml PHP Module must also be version 2.7.8 or higher.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:69:\"Contact your hosting provider to install the SimpleXML PHP extension.\";}}}i:5;a:4:{s:2:\"id\";i:6;s:7:\"isValid\";b:1;s:5:\"title\";s:17:\"WordPress Version\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:94:\"Your WordPress version is outdated. WPML requires at least <strong> WordPress 6.0.0</strong>. \";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:69:\"Please update your WordPress installation to version 6.0.0 or higher.\";}}}i:6;a:4:{s:2:\"id\";i:8;s:7:\"isValid\";b:1;s:5:\"title\";s:19:\"PHP eval() Function\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:114:\"The PHP eval() function is disabled by the Suhosin extension. WPML requires this function when Suhosin is enabled.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:122:\"Contact your hosting provider to enable the eval() function in the Suhosin configuration or disable the Suhosin extension.\";}}}i:7;a:4:{s:2:\"id\";i:9;s:7:\"isValid\";b:1;s:5:\"title\";s:17:\"libxml PHP Module\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:97:\"WPML requires libxml PHP Module version 2.7.8 or higher to process XML correctly using SimpleXML.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:63:\"Contact your hosting provider to upgrade the libxml PHP Module.\";}}}i:8;a:4:{s:2:\"id\";i:7;s:7:\"isValid\";b:1;s:5:\"title\";s:26:\"Multibyte String Extension\";s:8:\"messages\";a:2:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:164:\"The <a href=\"https://www.php.net/manual/en/book.mbstring.php\" target=\"_blank\">Multibyte String extension</a> is required to handle non-Latin character sets in WPML.\";}i:1;a:2:{s:4:\"type\";s:5:\"alert\";s:7:\"message\";s:87:\"Contact your hosting provider to install the Multibyte String (mbstring) PHP extension.\";}}}i:9;a:4:{s:2:\"id\";i:10;s:7:\"isValid\";b:1;s:5:\"title\";s:14:\"PHP Stack Size\";s:8:\"messages\";a:3:{i:0;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:69:\"WPML requires at least 208 KB of PHP stack size on PHP 8.3 or higher.\";}i:1;a:2:{s:4:\"type\";s:1:\"p\";s:7:\"message\";s:101:\"Add this to your <strong>php.ini</strong> and restart your web server to set the required stack size:\";}i:2;a:2:{s:4:\"type\";s:4:\"code\";s:7:\"message\";s:92:\"; Stack Size Configuration\nzend.max_allowed_stack_size = 256K\nzend.reserved_stack_size = 48K\";}}}}', 'off'),
